# CODEFORGE GROQ INTEGRATION PATCH 004
# Primary AI: Groq openai/gpt-oss-120b
# Secondary Groq model: openai/gpt-oss-20b
# External fallback: Gemini
# Run from either the CodeForge project root OR backend folder.
# This script NEVER prints or overwrites your GROQ_API_KEY value.

$ErrorActionPreference = "Stop"

$Here = (Get-Location).Path
if (Test-Path (Join-Path $Here "app\Services\AiAssistantService.php")) {
    $Backend = $Here
} elseif (Test-Path (Join-Path $Here "backend\app\Services\AiAssistantService.php")) {
    $Backend = Join-Path $Here "backend"
} else {
    throw "CodeForge backend not found. Run this script from the project root or backend folder."
}

$PHP = "D:\xampp\php\php.exe"
if (!(Test-Path $PHP)) {
    throw "XAMPP PHP was not found at $PHP"
}

$Service = Join-Path $Backend "app\Services\AiAssistantService.php"
$Config = Join-Path $Backend "config\ai_assistant.php"
$EnvFile = Join-Path $Backend ".env"
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($File in @($Service, $Config, $EnvFile)) {
    if (!(Test-Path $File)) {
        throw "Required file not found: $File"
    }
}

# Safety check: this patch is built for the current CodeForge Copilot service.
$ExistingService = [System.IO.File]::ReadAllText($Service, [System.Text.Encoding]::UTF8)
if ($ExistingService -notmatch "class AiAssistantService" -or
    $ExistingService -notmatch "askDeepSeekModel" -or
    $ExistingService -notmatch "askGeminiModel" -or
    $ExistingService -notmatch "buildModelMessages") {
    throw "AiAssistantService.php does not match the expected current CodeForge Copilot version. No files were changed."
}

$Backups = @{}

function Backup-File([string]$Path) {
    $Backup = "$Path.backup-groq004-$Stamp"
    Copy-Item $Path $Backup -Force
    $script:Backups[$Path] = $Backup
    Write-Host "[BACKUP] $Backup"
}

function Restore-Backups {
    Write-Host "[ROLLBACK] Restoring original files..."
    foreach ($Path in $script:Backups.Keys) {
        $Backup = $script:Backups[$Path]
        if (Test-Path $Backup) {
            Copy-Item $Backup $Path -Force
        }
    }
}

function Write-Base64File([string]$Path, [string]$Data) {
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Data))
}

function Read-Utf8([string]$Path) {
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $Encoding = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $Encoding)
}

function Set-EnvValue([string]$Text, [string]$Name, [string]$Value) {
    $Pattern = "(?m)^" + [regex]::Escape($Name) + "=.*$"
    $Replacement = "$Name=$Value"

    if ([regex]::IsMatch($Text, $Pattern)) {
        return [regex]::Replace($Text, $Pattern, $Replacement)
    }

    if (!$Text.EndsWith("`n")) {
        $Text += "`r`n"
    }

    return $Text + $Replacement + "`r`n"
}

try {
    Backup-File $Service
    Backup-File $Config
    Backup-File $EnvFile

    # Exact UTF-8/no-BOM source avoids the encoding problems from earlier patches.
    Write-Base64File $Service ""
    Write-Base64File $Config ""

    Write-Host "[FIX] Installed Groq provider support"
    Write-Host "[FIX] Primary model: openai/gpt-oss-120b"
    Write-Host "[FIX] Groq fallback model: openai/gpt-oss-20b"
    Write-Host "[FIX] Gemini remains external fallback"
    Write-Host "[FIX] DeepSeek code kept available but removed from the active chain"

    # Preserve all existing secret values. Add only a blank GROQ_API_KEY placeholder if missing.
    $EnvText = Read-Utf8 $EnvFile

    if ($EnvText -notmatch "(?m)^GROQ_API_KEY=") {
        if (!$EnvText.EndsWith("`n")) {
            $EnvText += "`r`n"
        }
        $EnvText += "GROQ_API_KEY=`r`n"
    }

    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_ENABLED" "true"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_PROVIDER" "groq"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_MODEL" "openai/gpt-oss-120b"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_GROQ_FALLBACK_MODEL" "openai/gpt-oss-20b"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_FALLBACK_PROVIDER" "gemini"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_FALLBACK_MODEL" "gemini-3.6-flash"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_TIMEOUT" "35"

    Write-Utf8NoBom $EnvFile $EnvText
    Write-Host "[FIX] AI environment settings updated; GROQ_API_KEY preserved"

    foreach ($File in @($Service, $Config)) {
        & $PHP -l $File
        if ($LASTEXITCODE -ne 0) {
            throw "PHP syntax validation failed: $File"
        }
    }

    Push-Location $Backend
    try {
        & $PHP artisan optimize:clear
        if ($LASTEXITCODE -ne 0) {
            throw "artisan optimize:clear failed"
        }
    } finally {
        Pop-Location
    }

    $FinalEnv = Read-Utf8 $EnvFile
    $KeyMatch = [regex]::Match($FinalEnv, "(?m)^GROQ_API_KEY=(.*)$")
    $HasKey = $KeyMatch.Success -and ($KeyMatch.Groups[1].Value.Trim().Length -gt 0)

    Write-Host ""
    Write-Host "[SUCCESS] Groq integration patch completed."
    Write-Host "Primary provider: groq"
    Write-Host "Primary model: openai/gpt-oss-120b"
    Write-Host "Groq fallback model: openai/gpt-oss-20b"
    Write-Host "External fallback: gemini"
    Write-Host "Groq key present: $HasKey"
    Write-Host ""

    if (!$HasKey) {
        Write-Host "MANUAL STEP: open backend\.env and set:"
        Write-Host "GROQ_API_KEY=YOUR_REAL_KEY"
        Write-Host "Then run: D:\xampp\php\php.exe artisan optimize:clear"
    } else {
        Write-Host "Your GROQ_API_KEY is already present."
    }

    Write-Host ""
    Write-Host "Restart backend:"
    Write-Host "D:\xampp\php\php.exe artisan serve --host=127.0.0.1 --port=8000"
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    Restore-Backups
    Write-Host "[ROLLBACK] Original files restored."
    exit 1
}
